def encode_navigation_state(position, target, obstacle_ahead):
    return {
        'position': float(position),
        'target': float(target),
        'distance_to_target': float(target - position),
        'obstacle_ahead': float(bool(obstacle_ahead))
    }

state = encode_navigation_state(position=2, target=8, obstacle_ahead=True)
print(state)

def navigation_reward(reached_goal, collision, step_cost=0.05):
    if collision:
        return -10.0
    if reached_goal:
        return 10.0
    return -abs(step_cost)

print(navigation_reward(False, False))
print(navigation_reward(True, False))
print(navigation_reward(False, True))

outcomes = [
    {'name': 'goal reached safely', 'goal': True, 'collision': False},
    {'name': 'ordinary movement', 'goal': False, 'collision': False},
    {'name': 'collision before goal', 'goal': False, 'collision': True},
    {'name': 'goal reached after collision', 'goal': True, 'collision': True}
]

for outcome in outcomes:
    reward = navigation_reward(outcome['goal'], outcome['collision'])
    print(outcome['name'], '->', reward)

ACTIONS = {0: 'left', 1: 'right', 2: 'up', 3: 'down'}

def action_name(action):
    if action not in ACTIONS:
        raise ValueError(f'Invalid action: {action}')
    return ACTIONS[action]

for action in range(len(ACTIONS)):
    print(action, action_name(action))

